const CACHE='homework-apprentice-v13';
const CORE=['./','./index.html','./style.css','./app.js','./data.js','./lore.js','./icon.svg','./icon-192.png','./icon-512.png','./icon-180.png','./manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('homework-apprentice-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(event.request);if(event.request.destination==='image'&&cached)return cached;try{const fresh=await fetch(event.request);if(fresh.ok)await cache.put(event.request,fresh.clone());return fresh;}catch{if(cached)return cached;if(event.request.mode==='navigate')return cache.match('./index.html');return new Response('',{status:503,statusText:'Offline asset unavailable'});}})());});
